if(screen==="setup"){ensureInitialRoster(t);html=initialRosterHTML(t)}
if(screen==="recruit"){const p=t.offer;if(!p){html=head("선수 영입","다음 승리 뒤, 새로운 선수가 찾아옵니다.")+'<button data-go="home">구단으로</button>'}else html=head("새로운 선수가 찾아왔습니다","영입하거나 15코인을 받은 뒤 다음 경기를 시작할 수 있습니다.")+'<section class="panel scout rec-card"><div class="grid2"><div class="stack"><span class="eyebrow gold">NEW PLAYER</span><div class="jersey-preview"><canvas data-portrait="offer" class="portrait" style="width:165px;height:192px"></canvas></div><h2>'+esc(p.name)+' <span class="muted">#'+p.number+'</span></h2><p class="muted">'+p.hand+' · '+p.tendency+'</p><p>“오늘도 열심히 하겠습니다.<br>판단은… 해보겠습니다.”</p></div><div class="stack">'+statBars(p)+'<p class="tiny muted">선수단 '+t.players.length+'/35 · 영입 비용 없음</p><button class="primary" data-action="accept-offer">우리 팀으로 영입</button><button data-action="reject-offer">영입 대신 15코인 받기</button></div></div></section>'}
if(screen==="settings"){html=head("우리 팀 설정","이름, 유니폼, 경기 속도와 저장 자료를 관리합니다.")+'<div class="grid2"><section class="panel stack"><label>팀 이름<input id="editTeamName" maxlength="12" value="'+esc(t.name)+'" style="display:block;width:100%;margin-top:8px" '+(t.match&&!t.match.done?"disabled":"")+'></label><button data-action="rename-team" '+(t.match&&!t.match.done?"disabled":"")+'>팀 이름 저장</button>'+colorPicker()+'<div class="jersey-preview" id="jerseyPreview"></div><button data-action="save-colors" '+(t.match&&!t.match.done?"disabled":"")+'>유니폼 배색 저장</button></section><section class="panel stack"><h3>경기 설정</h3><label>자동 경기 움직임 속도<select id="speed" style="width:100%;display:block;margin-top:8px">'+[1,2,3].map(n=>'<option value="'+n+'" '+(data.settings.speed===n?"selected":"")+'>'+n+'배 · '+(n===1?"기본":n===2?"빠르게":"더 빠르게")+'</option>').join("")+'</select></label><button data-action="sound">효과음 '+(data.settings.sound?"켜짐":"꺼짐")+'</button><p class="tiny muted">공격·수비 선택은 10초, 사건 멘트는 5초 표시됩니다. 지시 버튼이나 그대로 해를 누르면 즉시 진행합니다. 주요 결과는 최소 3초, 홈런은 4.5초 확인합니다. 수비 지시 시에는 짧게 위치를 옮긴 뒤 투구합니다. 우리 팀 본헤드는 한 회의 초·말 합산 최대 3번입니다.</p><hr style="width:100%;border:0;border-top:1px solid #365777"><h3>저장 '+(data.current+1)+'</h3><button data-action="backup" data-i="'+data.current+'">이 팀의 백업 파일 내려받기</button><button data-action="import" data-i="'+data.current+'">백업 파일 불러오기</button><button data-go="slots">두 저장칸 보기</button><button class="danger" data-action="reset-slot" data-i="'+data.current+'">이 팀을 처음부터 다시 하기</button><details class="audit"><summary>규칙 점검과 실행 상태</summary><button class="small" data-action="rule-check">경기 외 규칙 점검</button><div id="ruleResults"></div><p class="tiny muted">플레이 경기를 추가로 만들지 않는 개별 판정 확인입니다.</p><p>화면 오류: '+runtimeErrors.length+'건</p></details></section></div>'}
if(screen==="records"){html=head("기록실","우리가 함께 만든 경기의 흔적들.")+'<div class="panel"><div class="row between"><h3>'+t.w+'승 '+t.l+'패 '+t.d+'무</h3><span class="gold">총 '+(t.w+t.l+t.d)+'경기 완료</span></div>'+t.history.map((h,i)=>'<details class="audit"><summary>'+esc(h.result)+' · '+esc(h.opp)+' · '+h.score.join(" : ")+' · '+h.coins+'코인</summary>'+auditHTML(h)+'</details>').join("")+(!t.history.length?'<p class="muted" style="margin-top:20px">아직 완료한 경기가 없습니다.</p>':"")+'</div>'}
