assert("무사 1·3루 병살 · 2아웃과 득점",()=>{const {m,ids}=fixture();m.bases=[ids[0],null,ids[2]];const e=emptyEvent(m);groundOut(m,e,true);return m.outs===2&&m.score[0]===1&&m.order[0]===1});
assert("포구 뒤 귀루 실패 · 타순은 한 칸",()=>{const {m,ids}=fixture();m.bases[0]=ids[0];const e=emptyEvent(m);flyOut(m,e,3);return m.outs===2&&m.order[0]===1&&m.bases[0]===null});
assert("희생플라이 · 득점·타점·타수 제외",()=>{const {m,ids}=fixture();m.bases[2]=ids[2];const b=batter(m),e=emptyEvent(m);flyOut(m,e,10);return m.score[0]===1&&b.stats.sf===1&&b.stats.rbi===1&&b.stats.ab===0});
assert("만루 홈런 · 4득점과 순서대로 베이스 순회",()=>{const {m,ids}=fixture();m.bases=ids;const e=emptyEvent(m);reachHit(m,e,4);const move=e.moves.find(x=>x.from===0);return m.score[0]===4&&e.runs.length===4&&move.points.length===5&&move.points[1][0]===650&&move.points[2][1]===230&&move.points[3][0]===250});
assert("도루 실패 · 타석과 타순 유지",()=>{const {m,ids}=fixture();m.bases[0]=ids[0];const e=emptyEvent(m);runnerEvent(m,e,"steal",6);return m.outs===1&&m.order[0]===0&&e.pa===false&&e.pitchThrown===false});
assert("태그 누락 · 베이스만 밟으면 세이프",()=>{const {m,ids}=fixture();m.bases[0]=ids[0];const e=emptyEvent(m);runnerEvent(m,e,"steal",9);return m.outs===0&&m.bases[1]===ids[0]});
