function ensurePlayerLooks(t){if(!t?.players)return;const used=new Set();for(const p of t.players){if(!Number.isInteger(p.look)||p.look<0||p.look>=PLAYER_LOOKS.length||used.has(p.look))p.look=PLAYER_LOOKS.findIndex((_,i)=>!used.has(i));used.add(p.look)}if(t.offer&&(!Number.isInteger(t.offer.look)||used.has(t.offer.look)))t.offer.look=PLAYER_LOOKS.findIndex((_,i)=>!used.has(i));if(t.match?.opp)ensurePlayerLooks(t.match.opp)}
