function slotsArtworkHTML(){return head("저장 선택","소중한 팀의 이야기를 이어가세요.")+'<section class="scene-frame scene-exterior slot-stage"><div class="slotcards">'+data.slots.map((s,i)=>'<section class="panel slot '+(!s?"empty":"")+'"><div class="row between"><span class="number">0'+(i+1)+'</span><h2>'+esc(s?.name||"빈 저장칸")+'</h2></div><canvas class="slot-thumb" data-slot-art="'+i+'" width="450" height="165"></canvas><p style="text-align:center;margin:8px 0">'+(s?s.w+'승 '+s.l+'패 '+s.d+'무 · 선수 '+s.players.length+'/35':"아직 시작하지 않은 이야기입니다.")+'</p>'+(s?.match&&!s.match.done?'<p class="gold" style="text-align:center">'+s.match.inning+'회 '+(s.match.half?"말":"초")+' · 이어할 경기</p>':"")+'<div class="buttons">'+(s?'<button class="primary" data-action="load-slot" data-i="'+i+'">불러오기 · 저장 '+(i+1)+'</button><button class="small" data-action="backup" data-i="'+i+'">백업</button><button class="small danger" data-action="delete-slot" data-i="'+i+'">삭제</button>':'<button class="primary" data-action="new-slot" data-i="'+i+'">새 게임 · 저장 '+(i+1)+'</button>')+'<button class="small" data-action="import" data-i="'+i+'">파일 불러오기</button></div></section>').join("")+'</div></section>'}
function createArtworkHTML(){return head("팀 만들기","우리 팀의 이름과 유니폼 색상을 골라주세요.")+'<section class="scene-frame scene-locker create-layout"><div class="panel stack"><label>팀 이름 · 1~12자<input id="teamName" maxlength="12" value="해체 드림즈" style="display:block;width:100%;margin-top:5px"></label><div class="color-groups">'+colorPicker()+'</div><div class="row"><button data-go="slots">‹ 이전</button><button class="primary" data-action="create-team" style="flex:1;font-size:20px">우리 팀 만들기</button></div></div><div class="uniform-fitting"><div class="fitting-light"></div><div class="jersey-preview" id="jerseyPreview"></div></div></section>'}
function homeArtworkHTML(t){const ace=t.players.length?t.players.reduce((a,b)=>Math.max(...Object.values(a.a))>Math.max(...Object.values(b.a))?a:b):null;return head("팀 메인","오늘도, 야구하기 좋은 날입니다.")+'<section class="scene-frame scene-exterior club-stage"><div class="club-menu"><button class="primary" data-action="'+(t.offer?"recruit":t.match&&!t.match.done?"resume-home":"start")+'">⚾ '+(t.offer?"새 선수 확인":t.match&&!t.match.done?"경기 이어하기":needsSetup(t)?setupStage(t)==="pending"?"바로 시작":"첫 경기 준비":"경기 시작")+'</button><button data-go="lineup">▤ 라인업</button><button data-go="players">♟ 선수 관리</button><button data-go="growth">↗ 선수 성장</button><button data-go="records">▥ 기록실</button><button data-go="settings"><small>⚙ 설정 · 연출 미리보기</small></button><button data-go="slots"><small>▣ 저장칸 보기</small></button></div><div class="field-note">야구는<br>언제 끝날지 몰라도<br>오늘은 한다.</div><canvas class="club-cast" id="clubCast" width="760" height="350"></canvas><aside class="club-report"><section class="panel stack"><h2>'+esc(t.name)+'</h2><div class="row between"><span>선수</span><b>'+t.players.length+' / 35</b></div><div class="row between"><span>기록</span><b>'+t.w+'승 '+t.l+'패 '+t.d+'무</b></div><p class="tiny">완료 보상 · 기본 1 + 우리 득점</p></section><section class="panel stack ace"><h3>오늘의 기대주</h3>'+(ace?'<canvas class="portrait" data-portrait="'+ace.id+'"></canvas><b style="text-align:center">'+esc(ace.name)+' #'+ace.number+'</b>':'<p>바로 시작에서<br>선수 12명을 만나보세요.</p>')+'<p style="text-align:center">“언젠가 해체될 팀도,<br>오늘은 이긴다.”</p></section></aside></section>'}
function lineArtworkHTML(t){const locked=!!(t.match&&!t.match.done),d=battingDraft(t),count=d.filter(x=>x.id).length;lineupFocus=clamp(lineupFocus,0,8);
return head(needsSetup(t)?"첫 경기 준비 · 타순 정하기":"타순 정하기","빈 타순 칸을 누르고, 오른쪽 선수 이름을 고르세요.",'<button class="primary" data-action="lineup-start" '+(locked||count<9?'disabled':'')+'>'+(needsSetup(t)?"이 편성으로 첫 경기 시작":"이 편성으로 경기 시작")+'</button>')+
(needsSetup(t)?'<div class="setup-progress"><span>✓ 선수 12명 합류</span><span>✓ 이름·등번호</span><b>③ 타순·수비 위치</b><button class="small" data-action="setup-back">이름·등번호 수정</button></div>':'')+
'<div class="simple-lineup all-abilities"><section class="panel batting-board"><div class="row between"><h3>타순 <span class="gold">'+count+' / 9</span></h3><button class="small" data-action="lineup-clear" '+(locked?'disabled':'')+'>모두 비우기</button></div><div class="batting-slots">'+d.map((v,i)=>{const p=ply(t,v.id);return '<article class="batting-slot '+(i===lineupFocus?'focused ':'')+(!p?'vacant':'')+'"><button class="slot-pick" data-action="lineup-select" data-i="'+i+'" aria-pressed="'+(i===lineupFocus)+'" '+(locked?'disabled':'')+'><b class="slot-order">'+(i+1)+'</b>'+(p?'<canvas data-portrait="'+p.id+'"></canvas><span>'+esc(p.name)+' <small>#'+p.number+'</small></span>':'<span class="slot-plus">＋</span><span>선수 지정</span>')+'</button>'+(p?'<div class="slot-bottom"><select data-draft-position="'+i+'" aria-label="'+(i+1)+'번 수비 위치" '+(locked?'disabled':'')+'>'+POS.map(pos=>'<option value="'+pos+'" '+(pos===v.pos?'selected':'')+'>'+POSITION_NAMES[pos]+'</option>').join('')+'</select><button class="slot-remove" data-action="lineup-remove" data-i="'+i+'" aria-label="'+(i+1)+'번 선수 빼기" '+(locked?'disabled':'')+'>×</button></div>':'')+'</article>'}).join('')+'</div><p class="lineup-help">'+(locked?'경기 중에는 편성을 바꿀 수 없습니다.':'×로 비우기 · 수비 위치는 선수 옆에서 선택')+'</p></section>'+
'<section class="panel roster-board"><div class="row between"><h3>우리 선수 · 전체 능력치</h3><b class="gold" id="assignTarget">'+(locked?'출전 명단':(lineupFocus+1)+'번에 들어갈 선수')+'</b></div><div class="ability-table-wrap"><table class="ability-table"><thead><tr><th>선수 · 등번호</th>'+KEYS.map(k=>'<th scope="col">'+(k==="sense"?'야구<br>센스':STATS[k])+'</th>').join('')+'<th>타순</th></tr></thead><tbody>'+t.players.map(p=>{const used=d.findIndex(x=>x.id===p.id),focused=d[lineupFocus].id===p.id;return '<tr class="'+(focused?'viewing ':'')+(used>=0?'assigned':'')+'" data-player-row="'+p.id+'"><th scope="row"><button class="roster-choice" data-action="lineup-assign" data-id="'+p.id+'" '+(locked||used>=0?'disabled':'')+'><canvas data-portrait="'+p.id+'"></canvas><span><b>'+esc(p.name)+' <strong class="jersey-id">#'+p.number+'</strong></b><small>'+p.hand+' · '+p.tendency+'</small></span></button></th>'+KEYS.map(k=>'<td class="'+(p.a[k]>=75?'high':p.a[k]<=25?'low':'')+'" data-stat="'+k+'">'+p.a[k]+'</td>').join('')+'<td>'+(used>=0?(used+1)+'번':'—')+'</td></tr>'}).join('')+'</tbody></table></div><p class="lineup-help"><span class="high">75 이상</span> · <span class="low">25 이하</span>　|　투수는 구속·제구, 수비수는 야구센스·포구·송구도 확인하세요.</p></section></div>'
}
function playerListHTML(t){return '<aside class="panel playerlist"><h3>선수 목록　'+t.players.length+'/35</h3>'+t.players.map(p=>'<button data-action="select-player" data-id="'+p.id+'" class="'+(p.id===selection?"selected":"")+'"><span class="row"><canvas class="mini-face" data-portrait="'+p.id+'"></canvas>'+esc(p.name)+'</span><span>#'+p.number+'</span></button>').join("")+'</aside>'}
function playersArtworkHTML(t){const p=ply(t,selection)||t.players[0];selection=p.id;return head("선수 관리","선수를 관리하고, 더 좋은 선수를 만들어가세요.")+'<section class="scene-frame scene-locker management">'+playerListHTML(t)+'<section class="panel player-profile"><h3>선수 정보</h3><div class="row"><canvas class="portrait" data-portrait="'+p.id+'"></canvas><div><h2>'+esc(p.name)+'</h2><p class="gold">#'+p.number+'</p><p>'+p.hand+' · '+p.tendency+'</p><button class="small" data-action="edit-player" '+(t.match&&!t.match.done?"disabled":"")+'>이름·등번호 수정</button></div></div>'+statBars(p)+'<p class="muted tiny">평범한 선수도, 특별한 이야기를 만듭니다.</p></section><section class="panel"><h3>누적 개인 기록</h3>'+playerRecords(p)+'</section></section>'}
function growthArtworkHTML(t){const p=ply(t,selection)||t.players[0];selection=p.id;const locked=t.match&&!t.match.done;return head("선수 성장","선수의 능력을 선택해 성장시킵니다.")+'<section class="scene-frame scene-training training-layout"><div class="practice-view"><div class="field-note">오늘도<br>조금 더<br>강해지자!</div><canvas id="practiceCast" width="500" height="350"></canvas></div><section class="panel stack"><h3>훈련할 선수</h3><select id="growthPlayer">'+t.players.map(x=>'<option value="'+x.id+'" '+(x.id===p.id?"selected":"")+'>'+esc(x.name)+' #'+x.number+'</option>').join("")+'</select><canvas class="portrait" data-portrait="'+p.id+'" style="width:130px;height:156px;align-self:center"></canvas><h2>'+esc(p.name)+'</h2><p class="gold">#'+p.number+' · '+p.hand+'</p><p class="muted">'+p.tendency+'</p><p>“좋은 선수가<br>언젠간 해체된다.”</p></section><section class="panel stack" id="trainingPanel"><h3>능력 성장</h3>'+KEYS.map(k=>'<div class="trainingrow"><span>'+STATS[k]+'</span><b>'+p.a[k]+' <span class="muted">→ '+Math.min(100,p.a[k]+1)+'</span></b><button class="small primary" data-action="train" data-stat="'+k+'" '+(locked||!cost(p.a[k])||t.coins<cost(p.a[k])?"disabled":"")+'>'+(p.a[k]===100?"최대":'<span class="coin-icon" aria-label="코인">₵</span> × '+cost(p.a[k]))+'</button></div>').join("")+'<div class="row between"><span>보유 코인</span><h2 class="gold">● '+t.coins+'</h2></div><p class="tiny muted">한 번에 +1 성장 · 성장 전 능력치에 따라 코인 비용이 달라집니다.</p></section></section>'}
function recruitArtworkHTML(t){const p=t.offer;if(!p)return head("선수 영입","다음 승리 뒤 새로운 선수가 찾아옵니다.")+'<section class="scene-frame scene-locker" style="min-height:540px;padding:35px"><button data-go="home">구단으로</button></section>';return head("신규 선수 영입","멋진 선수가 팀에 합류하려 합니다!")+'<section class="scene-frame scene-locker scout-layout"><div class="scout-reveal"><span class="new-stamp">NEW!</span><canvas class="portrait" data-portrait="offer"></canvas><h2>'+esc(p.name)+' #'+p.number+'</h2><blockquote>“언제나 더 높은 곳을 바라봅니다.<br>팀에 도움이 되고 싶습니다!”</blockquote></div><section class="panel stack"><h3>선수 능력치</h3>'+statBars(p)+'<p class="muted">'+p.hand+' · '+p.tendency+'　/　선수단 '+t.players.length+'/35</p><button class="primary" data-action="accept-offer" style="font-size:22px">영입하기</button><button data-action="reject-offer">대신 15코인 받기</button><p class="tiny">영입 또는 코인 수령을 결정하면 다음 경기를 준비합니다.</p></section></section>'}
function resultArtworkHTML(){const t=team(),m=t.match;if(!m?.done)return "";return head("경기 결과 · "+m.result,"오늘의 경기가 우리 팀의 기록이 됩니다.")+'<section class="scene-frame scene-stadium result-stage"><div class="result-title '+(m.result==="패배"?"bad":"")+'">'+(m.result==="승리"?"❧　승리　❧":m.result)+'<div class="resultscore">'+m.score.join(" : ")+'</div><p style="font-size:15px;color:#fff">'+m.inning+'회 종료 · '+esc(t.name)+' vs '+esc(m.opp.name)+'</p></div><div class="result-grid" style="margin-top:15px"><section class="panel">'+inningsHTML(m)+'</section><section class="panel stack"><h3>획득 보상</h3><div class="row between"><span>기본 1 + 득점 '+m.score[0]+'</span><h2 class="gold">'+m.reward+' 코인</h2></div><div class="row between"><span>승리 트로피</span><b>+'+(m.result==="승리"?1:0)+'</b></div><p class="tiny">본헤드 · 우리 '+m.bh[0]+' / 상대 '+m.bh[1]+'　|　'+t.w+'승 '+t.l+'패 '+t.d+'무</p></section></div><canvas class="result-cast" id="resultCast" width="1100" height="240"></canvas><div class="result-next"><button data-action="review-game">경기 흐름 보기 ↓</button> <button class="primary" data-action="'+(t.offer?"recruit":"home")+'">'+(t.offer?"새 선수 확인":"다음 경기 준비")+'</button></div></section>'+gameSummaryHTML(m)+'<details class="panel audit"><summary>이번 경기 상세 기록 · '+m.pitches+'구</summary>'+auditHTML(m)+'</details>'}
function renderReaction(){updateControls();const host=$("#reactionHost");if(!host)return;if(!reaction){host.replaceChildren();return}let card=host.querySelector(".reaction");if(card?.dataset.event!==reaction.eventId){host.innerHTML='<div class="reaction" data-event="'+esc(reaction.eventId)+'"><div class="bubble"><small>'+esc(reaction.speaker)+'</small>'+esc(reaction.line)+'</div><canvas id="reactionPortrait" width="230" height="285" aria-label="'+esc(reaction.speaker)+'"></canvas></div>';card=host.firstElementChild}card.classList.toggle("leaving",reaction.left<250);const own=!reaction.speaker.startsWith("상대"),tm=reaction.speaker==="중계진"?{primary:4,secondary:3}:own?team():team().match.opp,role=reaction.speaker==="중계진"?"commentator":reaction.speaker.includes("치어")?"cheer":"fan",cv=$("#reactionPortrait"),c=cv.getContext("2d");card.dataset.bust=String(role==="cheer");if(role==="cheer"&&ART.ready){cv.width=260;cv.height=235;drawReactionBust(c,tm,role,["g03","g29"].includes(reaction.group)?"celebrate":own?"idle":"tease")}else{cv.width=230;cv.height=285;c.clearRect(0,0,230,285);sprite(c,115,273,role==="commentator"?2.75:2.7,tm,7,role,own?"idle":"tease",performance.now(),"s")}}

function reactionLabHTML(){return head("리액션 시안 4종","D 만화 컷을 경기 리액션에 적용했습니다. 다른 형태와 비교해 볼 수 있습니다.",'<button data-go="slots">저장 선택으로</button>')+
'<section class="reaction-lab" id="reactionLab"><div class="rx-tools"><label>화자 <select id="rxSpeaker">'+["우리 치어리더","상대 치어리더","중계진","우리 관객","상대 관객"].map((s,i)=>'<option value="'+i+'">'+s+'</option>').join('')+'</select></label><span class="tiny">상반신 · 한 번에 한 화자 · 5초</span></div><div class="rx-grid">'+[
 ["a","A · 깔끔한 중계 카드","부드러운 테두리"],
 ["b","B · 픽셀 말풍선","시안의 픽셀 분위기"],
 ["c","C · 반투명 티켓","작고 가벼운 배치"],
 ["d","D · 만화 컷","표정과 멘트 강조"]
 ].map(v=>'<article class="rx-option"><div class="rx-option-head"><div><b>'+v[1]+'</b><br><span>'+v[2]+'</span></div><button class="rx-replay" data-action="rx-replay" data-design="'+v[0]+'">등장·퇴장 보기</button></div><div class="rx-stage"><canvas class="rx-background" width="600" height="330" data-lab-scene="'+v[0]+'"></canvas><div class="rx-score">4회 초　우리 팀 0 : 2 상대 팀</div><div class="rx-card rx-'+v[0]+'" data-lab-card="'+v[0]+'"><div class="rx-copy"><small class="rx-speaker">우리 치어리더</small><div class="rx-bubble">응원은 제가 할게요.<br>야구는 누가 해요?</div></div><canvas class="rx-bust" data-lab-bust="'+v[0]+'" width="260" height="235" aria-label="치어리더 상반신"></canvas></div></div></article>').join('')+'</div></section>'
}
let labSpeaker=0;
function drawReactionLab(){const root=$("#reactionLab");if(!root||!ART.ready)return;const speakers=["우리 치어리더","상대 치어리더","중계진","우리 관객","상대 관객"],speaker=speakers[labSpeaker],own=team()||{primary:11,secondary:5},op=artOpponent(own),tm=labSpeaker===2?{primary:4,secondary:3}:[1,4].includes(labSpeaker)?op:own,role=labSpeaker===2?"commentator":labSpeaker>2?"fan":"cheer",messages=["응원은 제가 할게요. 야구는 누가 해요?","혹시 저희 팀 유니폼 필요하세요?","양보 정신이 훌륭하네요.","둘이나 있는데 그걸 안 잡아?","그렇게 주시면 저희는 감사하죠!"];root.style.setProperty("--rx-primary",COLORS[tm.primary][1]);root.style.setProperty("--rx-trim",COLORS[tm.secondary][1]);root.querySelectorAll(".rx-speaker").forEach(n=>n.textContent=speaker);root.querySelectorAll(".rx-bubble").forEach(n=>n.textContent=messages[labSpeaker]);root.querySelectorAll("[data-lab-bust]").forEach(cv=>{cv.setAttribute("aria-label",speaker+(role==="cheer"?" 상반신":""));drawReactionBust(cv.getContext("2d"),tm,role,[1,4].includes(labSpeaker)?"tease":"idle")});root.querySelectorAll("[data-lab-scene]").forEach(cv=>{const c=cv.getContext("2d");drawStadium(c,600,330,0);c.save();c.scale(600/900,330/530);for(const pos of ["P","SS","2B","LF","CF","RF"])sprite(c,...FIELD[pos],1,op,7,"player","idle",0,pos);c.restore()})}
