document.addEventListener("click",ev=>{
 const el=ev.target.closest("button");if(!el||el.disabled||!el.dataset.action?.startsWith("lineup-"))return;const t=team();if(!t||t.match&&!t.match.done)return;const act=el.dataset.action,d=battingDraft(t),i=Number(el.dataset.i);
 if(act==="lineup-select"){lineupFocus=i;render();return}
 if(act==="lineup-clear"){t.battingDraft=d.map(x=>({id:null,pos:x.pos}));lineupFocus=0}
 else if(act==="lineup-remove"){d[i].id=null;lineupFocus=i}
 else if(act==="lineup-assign"){if(!assignBattingSlot(t,lineupFocus,el.dataset.id))return;const next=d.findIndex((x,i)=>!x.id&&i>lineupFocus);lineupFocus=next>=0?next:Math.max(0,d.findIndex(x=>!x.id))}
 else if(act==="lineup-start"){const err=commitBattingDraft(t);if(err){toast(err);return}save();startMatch();return}
 else return;
 if(!t.battingDraft.some(x=>!x.id))commitBattingDraft(t);save();render()
});
