function playProgress(u){if(u>=1)return 1;return u<.55?u/.55*.36:.36+(u-.55)/.45*.64}
function batterPoseFor(e,t){return e?.swing&&t>.16&&t<.39?"swing":"bat"}
function pitchAction(e){if(!e)return "투구 준비";if(e.pitchThrown===false)return "주루 플레이";if(e.type==="hbp")return "공에 맞음";if(e.swing)return e.contact?"스윙 · 배트에 맞음":"스윙 · 헛스윙";if(["wp","pb"].includes(e.type))return "배트를 내지 않음";return "공을 지켜봄"}
function pitchExplanation(e){if(e.pitchThrown===false)return "투구 전 주루 상황 · 타자의 스윙 없음";if(!e.inputCommand)return "";const cmd={power:"풀스윙",contact:"컨택",take:"참아"}[e.inputCommand]||"기본 판단";let why="";if(!e.swing&&e.inZone===false&&["ball","bb"].includes(e.type))why=" · 바깥 공을 골라냈습니다";if(!e.swing&&e.inZone===true&&["strike","kl"].includes(e.type))why=" · 지켜본 공이 스트라이크였습니다";return "지시: "+cmd+" → 실제: "+pitchAction(e)+why}
function paintPitchAction(e,t){const host=$("#fieldStatus");if(!host||!e)return;const passed=t>=.22||e.pitchThrown===false;const key=e.id+":"+passed;if(host.dataset.phase===key)return;host.dataset.phase=key;const cmd={power:"풀스윙",contact:"컨택",take:"참아"}[e.inputCommand]||"기본 판단";host.innerHTML='<span class="pitch-order">'+(e.attack===0?"우리 타자":"상대 타자")+' · '+esc(e.batterName||"")+' · '+esc(cmd)+' 지시</span><span class="pitch-action">'+(passed?esc(pitchAction(e)):"투구 → 공을 보고 판단")+'</span>'}
function drawBatAction(c,e,t){if(!e?.pitchThrown||t<.16||t>.40)return;const sc=fieldScale(455),cv=c.canvas,ratio=(cv.clientWidth/cv.width)/(cv.clientHeight/cv.height)||1;c.save();c.translate(ply(tside(team().match,e.attack),e.batter)?.hand==="좌타"?478:422,455);c.scale(sc,sc*ratio);if(e.swing){const u=clamp((t-.16)/.08,0,1);c.globalAlpha=Math.sin(clamp((t-.16)/.24,0,1)*Math.PI)*.8;c.lineWidth=3;c.strokeStyle="#fff7b5";c.beginPath();c.ellipse(8,-37,28,9,-.15,Math.PI*.92,Math.PI*(.92+u*1.25));c.stroke();if(e.contact&&t>=.22&&t<.28){c.globalAlpha=1;for(let i=0;i<6;i++){const a=i*Math.PI/3;line(c,[[15+Math.cos(a)*6,-37+Math.sin(a)*6],[15+Math.cos(a)*13,-37+Math.sin(a)*13]],"#fff1a0",2)}}}else{c.globalAlpha=.95;textAt(c,"지켜봄",0,-62,10,"#fff4ba")}c.restore()}

function recordRecap(m,e){const add=x=>{m.recap.events++;if(x.attack===0){const v=m.recap.box[x.batter]??={id:x.batter,name:x.batterName,number:x.batterNumber,pa:0,ab:0,h:0,hr:0,k:0,whiff:0};v.pa+=Number(!!x.pa);v.ab+=Number(!!x.ab);v.h+=Number(x.hit>0);v.hr+=Number(x.hit===4);v.k+=Number(["ks","kl"].includes(x.type));v.whiff+=Number(!!x.swing&&!x.contact)}if(x.runs.length||x.bh||["dp","flydp","cs"].includes(x.type)){const copy={};for(const k of ["id","inning","half","attack","type","text","bh","bhSide","bhActors","batter","batterName","batterNumber","runs","outsAdded"])copy[k]=x[k];copy.before={score:x.before.score.slice()};copy.after={score:x.after.score.slice()};m.recap.highlights.push(copy)}};if(!m.recap){m.recap={box:{},highlights:[],events:0};(m.events||[]).forEach(add)}add(e)}
function gameStory(m){const high=summaryHighlights(m),first=high.find(e=>e.runs.length),all=[];for(let side=0;side<2;side++)(m.innings?.[side]||[]).forEach((runs,i)=>{if(runs>0)all.push({side,runs,i})});all.sort((a,b)=>b.runs-a.runs||a.i-b.i);const biggest=all[0],own=all.filter(x=>x.side===0)[0],sentences=[];if(first)sentences.push(first.inning+'회 '+(first.half?'말':'초')+'에 '+(first.attack===0?'우리 팀':'상대 팀')+'이 먼저 득점했습니다.');if(biggest)sentences.push('가장 크게 점수가 난 장면은 '+(biggest.i+1)+'회 '+(biggest.side===m.home?'말':'초')+', '+(biggest.side===0?'우리 팀':'상대 팀')+'의 '+biggest.runs+'득점이었습니다.');if(own&&biggest?.side!==0)sentences.push('우리 팀은 '+(own.i+1)+'회에 '+own.runs+'점을 기록했습니다.');if(!first)sentences.push('양 팀 모두 득점하지 못했습니다.');return sentences.join(' ')}

function summaryHighlights(m){if(m.recap?.highlights)return m.recap.highlights;return (m.events||[]).filter(e=>e.runs.length||e.bh||["dp","flydp","cs"].includes(e.type))}
function gameSummaryHTML(m){const ev=m.events||[],hs=m.hits||[0,1].map(side=>ev.filter(e=>e.attack===side&&e.hit>0).length),bh=Array.isArray(m.bh)?m.bh:m.boneheads||[m.bh||0,ev.filter(e=>e.bh&&e.bhSide===1).length],high=summaryHighlights(m),innings=m.innings||[[],[]],rows=[];
 for(let n=0;n<7;n++){if(innings[0][n]==null&&innings[1][n]==null)continue;const plays=high.filter(e=>e.inning===n+1),sc=[0,1].map(side=>innings[side].slice(0,n+1).reduce((a,b)=>a+(b||0),0));rows.push('<details><summary>'+(n+1)+'회 · 우리 '+(innings[0][n]===null?'공격 없음':innings[0][n]+'점')+' / 상대 '+(innings[1][n]===null?'공격 없음':innings[1][n]+'점')+' <span class="muted">　누적 '+sc.join(' : ')+'</span></summary>'+plays.map(e=>{const name=e.batterName||(e.attack===0?ply(team(),e.batter)?.name:null)||"상대 타자",lead=e.runs.length&&e.before.score[0]!==e.before.score[1]&&e.after.score[0]===e.after.score[1]?" · 동점":e.runs.length&&(e.before.score[0]-e.before.score[1])*(e.after.score[0]-e.after.score[1])<0?" · 역전":"";return '<div class="summary-play"><b>'+(e.half?'말':'초')+' · '+(e.attack===0?'우리 팀':'상대 팀')+' '+e.after.score.join(' : ')+lead+'</b><p>'+esc(eventCaption(e))+'</p><small>'+esc(name)+(e.batterNumber!==undefined?' #'+e.batterNumber:'')+(e.runs.length?' · '+e.runs.length+'득점':'')+'</small></div>'}).join('')+(!plays.length?'<p class="summary-empty">이 이닝의 득점·본헤드·병살·도루 저지 장면이 없습니다.</p>':'')+'</details>')}
 return '<section class="panel game-summary"><div class="row between"><h3>경기 돌아보기 · '+esc(m.result||"기록")+'</h3>'+(m.skipped?'<span class="pill gold">남은 경기 스킵 완료</span>':'')+'</div><p class="muted tiny">실제 판정으로 기록한 경기 흐름 · 숫자는 우리 팀 / 상대 팀 순서입니다.</p><p class="summary-story">'+esc(gameStory(m))+'</p><div class="summary-metrics"><div><small>득점</small><strong>'+m.score.join(' / ')+'</strong></div><div><small>안타</small><strong>'+hs.join(' / ')+'</strong></div><div><small>본헤드</small><strong>'+bh.join(' / ')+'</strong></div><div><small>양 팀 투구 수</small><strong>'+m.pitches+'</strong></div></div>'+inningsHTML(m)+'<div class="summary-innings">'+rows.join('')+'</div>'+gameBox(m)+'</section>'}
function recordsArtworkHTML(t){return head("기록실","경기 결과와 이닝별 흐름을 다시 살펴보세요.")+'<div class="records-layout"><figure class="records-art" style="margin:0"><canvas id="recordsArt" width="900" height="675" role="img" aria-label="전체 구장 정면 배경"></canvas><figcaption>'+esc(t.name)+' · '+t.w+'승 '+t.l+'패 '+t.d+'무<br><small>한 경기씩 쌓인, 우리 팀의 이야기.</small></figcaption></figure><section class="records-list">'+(t.history.length?t.history.map((h,i)=>'<details class="panel" '+(i===0?'open':'')+'><summary><b class="'+(h.result==='승리'?'gold':h.result==='패배'?'bad':'good')+'">'+h.result+'　'+h.score.join(' : ')+'</b>　'+esc(h.opp)+'<small class="muted">　'+new Date(h.at).toLocaleDateString('ko-KR')+'</small></summary>'+gameSummaryHTML(h)+'<details class="audit"><summary>플레이·멘트 상세 기록</summary>'+auditHTML(h)+'</details></details>').join(''):'<div class="panel stack"><h3>첫 경기를 기다립니다.</h3><p class="muted">경기를 마치면 결과, 이닝별 득점, 주요 장면이 이곳에 남습니다.</p><button data-go="home">구단 홈으로</button></div>')+'</section></div>'}
function skipChunk(m,limit=16){let n=0;while(!m.done&&n<limit){resolvePitch(m);n++}return n}
function paintSkipProgress(m,count){let host=$("#skipProgress");if(!host){host=document.createElement('div');host.id='skipProgress';host.className='skip-progress';host.setAttribute('role','status');document.body.append(host)}host.innerHTML='<div class="panel"><span class="eyebrow">FAST FORWARD</span><h2>남은 경기를 진행합니다</h2><span class="skip-spinner"></span><strong>'+m.score.join(' : ')+'</strong><p>'+m.inning+'회 '+(m.half?'말':'초')+' · '+count+'개 장면 진행</p><p class="tiny">기본 판단으로 진행한 뒤 기록과 주요 장면을 보여드립니다.</p></div>'}
async function skipRemainingMatch(){const m=team()?.match;if(!m||skipJob)return;if(m.done){anim=null;reaction=null;shiftLead=null;waitMs=0;go('result');return}const job={m};skipJob=job;m.skipped=true;m.paused=true;anim=null;reaction=null;shiftLead=null;waitMs=0;m.announcement=null;save(true);let count=0;paintSkipProgress(m,count);
 try{await new Promise(r=>setTimeout(r,80));while(!m.done&&count<2000){suppressPersist++;try{count+=skipChunk(m,16)}finally{suppressPersist--}save(true);paintSkipProgress(m,count);await new Promise(r=>setTimeout(r,16))}if(!m.done)throw Error('진행량이 많아 잠시 멈췄습니다. 마지막 판정부터 이어갈 수 있습니다.');}
 catch(err){m.paused=true;runtimeErrors.push('경기 스킵: '+err.message);toast(err.message)}
 finally{skipJob=null;$("#skipProgress")?.remove();save(true);go(m.done?'result':'match');if(m.done)requestAnimationFrame(()=>$(".game-summary")?.scrollIntoView({block:'start'}))}
}




